#!/usr/bin/env python3
"""Generate docs/coverage-ledger.md and docs/compatibility-matrix.md from catalog/*.json.

Usage: python scripts/generate_docs.py [--check]
--check exits 1 if the generated files differ from what is on disk.
"""
import json
import sys
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
STATUSES = ["not_started", "drafted", "executed_unreviewed", "verified"]
CLASSES = ["native", "adapted", "alt_env"]
HEADER = "<!-- Generated by scripts/generate_docs.py from catalog/*.json. Do not edit by hand. -->\n\n"


def load(name):
    return json.loads((ROOT / "catalog" / name).read_text(encoding="utf-8"))


def esc(text):
    return str(text).replace("|", "\\|")


def count_table(label, keys, recipes, field):
    c = Counter(r[field] for r in recipes)
    lines = [f"| {label} | Count |", "| --- | --- |"]
    lines += [f"| {k} | {c.get(k, 0)} |" for k in keys]
    lines.append(f"| total | {len(recipes)} |")
    return lines


def ledger():
    chapters = load("chapters.json")["chapters"]
    recipes = load("recipes.json")["recipes"]
    gaps = load("coverage_gaps.json")
    out = [HEADER + "# Coverage ledger\n"]
    out.append(
        "Status values: not_started, drafted, executed_unreviewed, verified. "
        "Nothing is marked verified without human review and real Databricks evidence.\n"
    )
    out += count_table("Status", STATUSES, recipes, "status") + [""]
    out.append("## Per chapter\n")
    for ch in chapters:
        rs = [r for r in recipes if r["chapter"] == ch["id"]]
        out.append(f"### Chapter {ch['id']}: {ch['title']}\n")
        out.append(f"Upstream folder: `{ch['upstream_folder']}`. Theme: {ch['theme']}.\n")
        out.append("| ID | Title | Class | Status | Upstream path |")
        out.append("| --- | --- | --- | --- | --- |")
        for r in rs:
            out.append(
                f"| {r['id']} | {esc(r['title'])} | {r['compatibility']} | {r['status']} | `{esc(r['upstream_path'])}` |"
            )
        out.append("")
    out.append("## Coverage gaps\n")
    out.append(f"- Expected total recipes: {gaps['expected_total']} ({gaps['expected_total_source']}).")
    out.append(f"- Recipes evidenced by upstream artifacts: {gaps['evidenced_count']}.")
    out.append(f"- Unaccounted for: {gaps['unaccounted_count']}.\n")
    out.append("| Chapter | Evidenced | Unconfirmed note |")
    out.append("| --- | --- | --- |")
    for g in gaps["per_chapter"]:
        out.append(f"| {g['chapter']} | {g['evidenced']} | {esc(g['unconfirmed_note'])} |")
    out.append("")
    out.append(gaps["note"] + "\n")
    return "\n".join(out)


def matrix():
    comp = load("compatibility.json")
    recipes = load("recipes.json")["recipes"]
    out = [HEADER + "# Compatibility matrix\n"]
    out.append(f"Classification status: **{comp['classification_status']}**.\n")
    out.append("## Classes\n")
    for k in CLASSES:
        out.append(f"- `{k}`: {comp['classes'][k]}")
    out.append("")
    out += count_table("Class", CLASSES, recipes, "compatibility") + [""]
    lim = comp["free_edition_limitations"]
    out.append("## Free Edition constraints (own summary)\n")
    out.append(f"Source: [Databricks Free Edition limitations]({lim['source']}), retrieved {lim['retrieved']}.\n")
    out += [f"- {s}" for s in lim["summary"]] + [""]
    out.append("## Per recipe\n")
    out.append("| ID | Title | Class | Alt env | Dependencies | Reason (preliminary) |")
    out.append("| --- | --- | --- | --- | --- | --- |")
    for r in recipes:
        reason = r["adaptation_notes"].split("Classification reason: ", 1)[-1]
        deps = ", ".join(r["dependencies"]) or "none"
        alt = "unresolved" if r.get("classification_unresolved") and not r["requires_alt_env"] else ("yes" if r["requires_alt_env"] else "no")
        out.append(
            f"| {r['id']} | {esc(r['title'])} | {r['compatibility']} | {alt} | {esc(deps)} | {esc(reason)} |"
        )
    out.append("")
    return "\n".join(out)


def main():
    targets = {ROOT / "docs" / "coverage-ledger.md": ledger(), ROOT / "docs" / "compatibility-matrix.md": matrix()}
    check = "--check" in sys.argv
    bad = False
    for path, text in targets.items():
        if check:
            if not path.exists() or path.read_text(encoding="utf-8") != text:
                print(f"OUT OF DATE: {path.relative_to(ROOT)}")
                bad = True
        else:
            path.parent.mkdir(exist_ok=True)
            path.write_text(text, encoding="utf-8")
            print(f"wrote {path.relative_to(ROOT)}")
    if check and not bad:
        print("docs up to date")
    return 1 if bad else 0


if __name__ == "__main__":
    sys.exit(main())
